import{_ as l,o as a,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"2019-12-03 -- Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-12-03 -- Crimson SeaStor OSD Weekly Meeting","date":"2019-12-03T00:00:00.000Z","updated":"2019-12-06T00:00:00.000Z","tags":["Ceph","分布式存储","代码优化","性能测试","内存管理","新设计方案"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-03_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-12-03_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-12-03_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function r(n,e,s,_,h,d){return a(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节： <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节：&quot;">​</a></h4><ul><li>会议主要讨论了Ceph存储系统中的多个技术问题，包括代码优化、性能测试、内存管理以及新的设计方案。</li><li>参会人员包括多位Ceph研发人员，如Anders、Radek等。</li></ul><h4 id="主要议题" tabindex="-1">主要议题： <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题：&quot;">​</a></h4><ol><li><p><strong>代码优化</strong>：</p><ul><li>讨论了使用单一锁（main lock）替代旧机制的可能性，以简化代码并提升查找表效率。</li><li>探讨了使用Clang编译器的问题，以及如何统一代码格式以提高开发效率。</li></ul></li><li><p><strong>性能测试</strong>：</p><ul><li>强调了在发布模式下进行性能测试的重要性，因为调试模式下的结果可能不准确。</li><li>分析了Ceph的Crimson版本与Classic版本在不同构建模式下的性能差异。</li></ul></li><li><p><strong>内存管理</strong>：</p><ul><li>提到了在特定条件下可能出现的内存分配问题，建议通过邮件详细讨论解决方案。</li></ul></li><li><p><strong>新设计方案</strong>：</p><ul><li>讨论了一个新的设计文档，涉及优化数据布局和垃圾收集策略，特别是在处理闪存系统时。</li><li>提出使用类似于日志结构文件系统的方法来减少写放大问题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ol><li><strong>性能测试</strong>：决定在发布模式下重新进行性能测试，以获得更准确的结果。</li><li><strong>代码优化</strong>：同意使用单一锁机制，并考虑统一代码格式。</li><li><strong>新设计方案</strong>：将继续研究和开发新的数据布局和垃圾收集策略。</li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ol><li><strong>性能测试</strong>：重新进行性能测试，并确保使用发布模式。</li><li><strong>代码优化</strong>：实施单一锁机制，并探索统一代码格式的可能性。</li><li><strong>新设计方案</strong>：继续研究和开发新的设计方案，并准备提交PR以供审查。</li></ol><h4 id="其他事项" tabindex="-1">其他事项： <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项：&quot;">​</a></h4><ul><li>会议中还提到了Ceph的Crimson版本的技术细节和未来的工作计划。</li><li>强调了在开发过程中保持沟通和协作的重要性。</li></ul><h4 id="结论" tabindex="-1">结论： <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论：&quot;">​</a></h4><p>会议集中讨论了Ceph存储系统的优化和性能提升，涉及代码结构、性能测试方法和新的设计理念。团队明确了下一步的工作重点和行动计划，以确保Ceph系统的稳定性和高效性。</p>',13)])])}const c=l(o,[["render",r]]);export{u as __pageData,c as default};
